import{_ as d,o,c,a3 as t}from"./chunks/framework.BZCmpA0A.js";const h=JSON.parse('{"title":"Spec 33：核心模組分層與圖形終端解耦","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-33-module-architecture.md","filePath":"SPEC-33-module-architecture.md","lastUpdated":1794034236000}'),r={name:"SPEC-33-module-architecture.md"};function a(s,e,i,l,n,u){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="spec-33-核心模組分層與圖形終端解耦" tabindex="-1">Spec 33：核心模組分層與圖形終端解耦 <a class="header-anchor" href="#spec-33-核心模組分層與圖形終端解耦" aria-label="Permalink to &quot;Spec 33：核心模組分層與圖形終端解耦&quot;">​</a></h1><p>日期：2026-11-07。</p><p>狀態：已實作並完成列出的建置、靜態檢查與 QEMU 驗收；限制見下方紀錄。</p><h2 id="目標與範圍" tabindex="-1">目標與範圍 <a class="header-anchor" href="#目標與範圍" aria-label="Permalink to &quot;目標與範圍&quot;">​</a></h2><p>在不改變 WUWAOS 現有功能與執行邊界的前提下，依職責整理 source tree，特別拆開 GUI、kernel TTY/I/O、process 與裝置驅動的依賴。維持單一固定 Terminal 視窗、既有 UART shell、系統呼叫 ABI、WUFS 格式、使用者程式連結內容、kernel/user 容量界線及現有命令和啟動方式。</p><p>本工作不新增視窗或 UI 功能，不搬移 UI 至 U-mode，不提供 POSIX PTY/window manager，也不改變排程或輸入輸出的既有可觀察順序。規格會以模組化 source tree 敘述目前 WUWAOS；不是動態載入核心模組、微核心或教科書中概念架構的宣稱。</p><h2 id="目標目錄" tabindex="-1">目標目錄 <a class="header-anchor" href="#目標目錄" aria-label="Permalink to &quot;目標目錄&quot;">​</a></h2><table tabindex="0"><thead><tr><th>區域</th><th>職責</th><th>主要來源</th></tr></thead><tbody><tr><td><code>arch/riscv/</code></td><td>啟動、陷阱、上下文切換、SBI、計時與 linker</td><td><code>entry.S</code>、<code>trap.S/C/H</code>、<code>swtch.S</code>、<code>context.h</code>、<code>sbi</code>、<code>timer</code>、<code>clock</code>、<code>linker.ld</code></td></tr><tr><td><code>drivers/uart/</code></td><td>UART MMIO 操作</td><td><code>uart.c/h</code></td></tr><tr><td><code>drivers/virtio/</code></td><td>VirtIO block、GPU、input 裝置</td><td><code>block</code>、<code>gpu</code>、<code>input</code></td></tr><tr><td><code>kernel/boot/</code></td><td>核心啟動與模組組裝</td><td><code>main.c</code></td></tr><tr><td><code>kernel/proc/</code></td><td>行程生命週期、排程、資源監測、窄 UI-facing service/event hook API</td><td><code>process</code>、<code>scheduler</code>、<code>workstate</code>、<code>terminal_service.h</code>、<code>event_hooks.h</code></td></tr><tr><td><code>kernel/mm/</code></td><td>頁面、虛擬記憶體與 swap</td><td><code>page</code>、<code>vm</code>、<code>swap</code></td></tr><tr><td><code>kernel/fs/</code></td><td>WUFS 和路徑查找</td><td><code>fs</code>、<code>path</code></td></tr><tr><td><code>kernel/io/</code></td><td>檔案描述符、核心 console、TTY</td><td><code>io</code>、<code>console</code>、<code>tty</code></td></tr><tr><td><code>kernel/ipc/</code></td><td>Mutex、Semaphore</td><td><code>sync</code></td></tr><tr><td><code>kernel/syscall/</code>、<code>kernel/exec/</code>、<code>kernel/lib/</code></td><td>syscall 分派、ELF/user image、核心記憶體函式</td><td>各自同名來源</td></tr><tr><td><code>ui/</code></td><td>核心內的桌面/視窗、VT model/render、圖形 primitive/font、鍵盤映射、splash</td><td><code>desktop</code>、<code>terminal/vt</code>、<code>terminal/renderer</code>、<code>graphics/primitives</code>、<code>input/keymap</code>、<code>assets</code>、<code>boot/splash</code></td></tr><tr><td><code>user/lib/</code>、<code>user/shell/</code>、<code>user/apps/</code></td><td>使用者 ABI/輸出函式庫、shell、互動程式</td><td><code>api</code>/<code>print</code>/entry、shell main/shell_exec/sync_demo、app demo、fan、workstate</td></tr><tr><td><code>include/</code></td><td>ABI、配置與各模組公開契約</td><td>保留目前公開 headers，按穩定用途整理</td></tr></tbody></table><p>精確檔名允許在實作時依現有介面調整；最終文檔必須與真實路徑一致。<code>kernel/desktop.c</code> 的整理必須拆成真實的責任模組，而非單純搬檔：圖形 primitives/font、桌布/視窗框/滑鼠游標/dirty composition、ANSI VT terminal model、keyboard mapping/input translation 分開。Renderer 僅繪製 terminal cells/characters/terminal cursor，不承接整個 desktop window composition。</p><h2 id="模組邊界與互動" tabindex="-1">模組邊界與互動 <a class="header-anchor" href="#模組邊界與互動" aria-label="Permalink to &quot;模組邊界與互動&quot;">​</a></h2><h3 id="tty-與-ui" tabindex="-1">TTY 與 UI <a class="header-anchor" href="#tty-與-ui" aria-label="Permalink to &quot;TTY 與 UI&quot;">​</a></h3><p>核心 <code>kernel/io/tty</code> 擁有 GUI 端點的 input/output rings 與 session 狀態。既有 CR/LF 與 raw-owner 狀態留在 <code>kernel/io/io</code>，不因分類搬動而改變。GUI 關閉只隱藏視窗，不終止 session。建立新 GUI shell 時初始化新 session；session leader 結束時由核心 I/O/TTY 清除 session 並將 ANSI alternate-screen/游標狀態復原。Process cleanup 不呼叫 UI 繪圖或 renderer。</p><p>TTY 提供窄介面：GUI session start/end/query、輸入 bytes push/read、輸出 bytes enqueue，以及註冊輸出 consumer。Desktop input adapter 將裝置事件映射為鍵盤字元，再透過 TTY push 輸入；核心 IO 只呼叫 TTY。TTY 輸出 consumer 在 boot 組裝時註冊為 UI VT feed/dirty callback。輸出 callback 將 bytes 餵入 ANSI VT model；VT model 持有 parser、cursor、色彩及 normal/alternate screen 狀態，不 include GPU、driver、process 或 TTY headers。Renderer 僅讀取 VT model 繪製 cell/字元/terminal cursor；window frame、wallpaper、mouse cursor 與全畫面 dirty composition 留在 desktop/window 模組，不得由 renderer 維護另一份 terminal state。</p><p>GUI 視窗啟動經 kernel-owned 的 <code>kernel/proc/terminal_service.h</code> 請求 <code>process_start_gui_terminal</code>；UI include 此公開核心服務 API，不暴露 Process 欄位。Process 不 include UI headers，也不直接呼叫 <code>desktop_*</code>；boot/main 是唯一裝配 UI callbacks/服務的位置。GUI session 的端點識別與 raw ownership 留在 kernel I/O，IO/console/process 不 include UI desktop headers。</p><h3 id="scheduler-與事件來源" tabindex="-1">Scheduler 與事件來源 <a class="header-anchor" href="#scheduler-與事件來源" aria-label="Permalink to &quot;Scheduler 與事件來源&quot;">​</a></h3><p>由 boot 裝配點註冊單一 UI <code>poll</code> 與 <code>active</code> callback 給 process event loop（目前 scheduler loop 實際位於 <code>process.c</code>）。保持目前 <code>process_resume</code> 與 scheduler loop 中的 <code>io_poll</code>、UI poll 相對順序及 idle 判斷；當 <code>current_index == -1</code> 時不得執行一般 syscall 或以不存在的 current process 存取 UI。此 callback 只抽離 UI 耦合，不增加新的事件來源或排程政策。</p><h3 id="input-與裝置" tabindex="-1">Input 與裝置 <a class="header-anchor" href="#input-與裝置" aria-label="Permalink to &quot;Input 與裝置&quot;">​</a></h3><p>VirtIO input driver 僅回報標準化事件，不 include GPU/UI headers。Pointer normalization 的最大座標透過 <code>input_set_pointer_bounds(max_x, max_y)</code> 注入；GPU bounds 由 boot/UI 配置。保留原 normalization 演算法和畫面 pixel 結果。</p><p>UART MMIO 移入 <code>drivers/uart</code>；kernel console 保留 routing、格式化與 log 行為，透過明確 UART API 操作裝置。其他 drivers 可繼續使用明確的 allocator/logging 介面。</p><h2 id="建置與相容" tabindex="-1">建置與相容 <a class="header-anchor" href="#建置與相容" aria-label="Permalink to &quot;建置與相容&quot;">​</a></h2><p>Makefile 使用明確的模組 source/object 路徑，最多保留 <code>-I.</code> 與 <code>-Iinclude</code>；不得把所有子目錄加入搜尋路徑，模組 include 使用可辨識的完整相對路徑。Nested dependency files 必須支援增量建置；clean 只刪除已知的 object/dependency/ELF/BIN build products（包含新 nested objects/deps 及舊 flat objects），不得遞迴刪除 <code>build/</code>，避免誤刪 disk images、swap、logs 或其他 scratch artifacts。維持 <code>build/kernel.elf</code>、<code>build/user.elf</code>、<code>build/app.elf</code>、<code>build/fan.elf</code>、<code>build/workstate.elf</code> 與 bins 名稱、連結順序、<code>-Oz</code>、run/run-gui 與 launcher targets。不得放寬 16 KiB user code 與 <code>0x80400000</code> kernel budget。</p><p>更新 <code>tools/make_desktop_font.ps1</code> 的預設輸出位置；更新 README、code guide 與當前架構 docs 的 GitHub source links。歷史規格保留原路徑與驗收文字；其中舊 <code>kernel/</code>、<code>user/</code> GitHub source links 固定到 refactor 前 commit <code>800a805</code>，不再連向不存在的舊 main 路徑。新增 modules 不更動 WUFS image format 或 package/archive entry behavior。</p><h2 id="驗收條件" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h2><ul><li>靜態檢查確認核心 IO/console/process 不 include <code>ui</code> headers，也不呼叫 <code>desktop_*</code>；VT model 無 GPU/driver/process/TTY include；input driver 無 GPU/UI include。</li><li>乾淨建置與再次增量建置均成功；clean 不留可誤用的 flat objects。既有輸出 ELF/BIN 名稱與旗標不變，使用者 binary 可逐位元比對；kernel 未超出原 linker budget。</li><li>使用獨立 scratch disk/swap 進行 UART 與 GUI QEMU 驗收：GUI shell 輸入輸出及 QMP 鍵盤/截圖、<code>fan</code> alternate-screen save/exit、<code>workstate</code> 的 <code>q</code>、GUI 隱藏/重開沿用原 session、<code>exit</code> 後新 session、無 GUI UART shell、pipe/redirection、WUFS 持久性。避免將新增測試程式碼或測試框架納入 repository。</li><li>文件網站建置通過，活躍程式碼連結對應到新路徑；原始 <code>build/wuwaos.img</code> 與 swap 在驗收前後 SHA-256 相同。</li></ul><h2 id="理論參考與實作區分" tabindex="-1">理論參考與實作區分 <a class="header-anchor" href="#理論參考與實作區分" aria-label="Permalink to &quot;理論參考與實作區分&quot;">​</a></h2><p>模組化核心邊界的概念可參考使用者筆記 <code>notes/ch2 Operating-System Structures.md</code>「作業系統服務與命令直譯器」；核心透過 I/O 服務隔離程式與裝置的概念可參考 <code>notes/ch12 I_O Systems.md</code>。這些筆記提供教科書觀念；WUWAOS 仍是單一靜態連結的 S-mode kernel，其 user shell 和應用程式以既有方式連結，UI 仍在 kernel 內執行。</p><h2 id="驗收紀錄" tabindex="-1">驗收紀錄 <a class="header-anchor" href="#驗收紀錄" aria-label="Permalink to &quot;驗收紀錄&quot;">​</a></h2><ul><li><code>make clean &amp;&amp; make -j2 all build/user.bin build/app.bin build/fan.bin build/workstate.bin build/kernel-disk.elf</code> 成功；後續增量建置無需重建。既有 user/app/fan/workstate BIN 與重構前 SHA-256 完全相同；kernel linker 成功，未調高既有 budget。完整輸出在忽略的 <code>build/architecture-clean-build.log</code>。</li><li>QMP 擷取重構前後 desktop 與初開 Terminal PPM，兩組 SHA-256 各自完全相同。QEMU GUI 驗收包含 shell help/pipe/redirection、Fan 儲存後離開、workstate <code>q</code>、視窗隱藏重開保留原 session，以及 shell <code>exit</code> 後開新 session。畫面在 <code>build/architecture-after-*.png</code>，UART trace 在 <code>build/architecture-after-uart.log</code>。</li><li><code>cat /home/user/ui.txt</code> 的穩定畫面顯示 <code>persist</code>；停止 GUI QEMU 後以 host 唯讀 parser 驗證 WUFS metadata，讀得 <code>b&#39;persist\\n&#39;</code>。另以無 GPU 的 UART QEMU 開機，確認既存檔 readback、<code>echo ui | cat</code>、檔案 redirection/write/readback；停止後唯讀驗證 <code>ui.txt</code> 與 <code>uart.txt</code> 的檔案 bytes 及全盤 metadata。</li><li><code>input.c</code>、VT model、core IO/console/process 的 include/call 邊界經靜態檢查；活動文件的 GitHub source links 均指向現行路徑，舊規格 source links 固定至 <code>800a805</code>。文件網站建置成功。</li><li>原始 <code>build/wuwaos.img</code> SHA-256 <code>6ba61b2e9e6c5af4931dd39d338619bf66bf25c5639bb916adc59b6b62fd4989</code>，原始 swap SHA-256 <code>f6ddb73f54cf434916200d752a0596b14da7d6534fe0f8cf454e6b1c02078355</code>；驗收全程使用獨立 <code>build/architecture-*.img</code> scratch disks。</li><li>限制：QEMU 驗收涵蓋互動、session 重開與已完成寫入的持久性，沒有做真實斷電/宿主崩潰測試，也沒有宣稱涵蓋所有裝置故障排列。這次只重整模組界面，未改核心演算法或 syscall/WUFS 格式。</li></ul>',28)])])}const b=d(r,[["render",a]]);export{h as __pageData,b as default};
